-- Hosbah (MH-575 F6): a data service's metrics history, sampled from db.insights (fixed, agent-owned
-- SQL — never a member's) roughly once a minute by the ops retention/sampling loop, one row per
-- service per minute (step 60). connections/max_connections/cache_hit_ratio/size_bytes/slow_query_count
-- are gauges read straight off the insights payload. tx_counter is the engine's cumulative counter
-- (Postgres: xact_commit + xact_rollback; MySQL: Questions) at sampling time; rate_per_sec is the
-- transactions/queries-per-second rate computed from the delta against the previous sample (0 on the
-- first sample for a service, or when the counter goes backwards — a restart). The retention job
-- (internal/dbmetrics) folds minute rows older than 24 h into 15-minute rows (step 900, gauges
-- averaged, rate_per_sec averaged, tx_counter kept as the latest in the bucket) and drops 15-minute
-- rows older than 30 days, mirroring server_metrics. Rows go with their service (and so with their team).
ALTER TABLE data_service_metrics ADD CONSTRAINT data_service_metrics_step_check CHECK (step IN (60, 900));
CREATE UNIQUE INDEX data_service_metrics_bucket_key ON data_service_metrics (service_id, step, at);
CREATE INDEX data_service_metrics_team_at_idx ON data_service_metrics (team_id, at);
CREATE INDEX data_service_metrics_step_at_idx ON data_service_metrics (step, at);
